    function () { var M1=rand(1,5)*1e24; var M2=rand(1,5)*1e24; var d=rand(1,10)*1e7; return {q:'M1='+(M1/1e24).toFixed(1)+'e24, M2='+(M2/1e24).toFixed(1)+'e24, d='+(d/1e6).toFixed(0)+' km. Zero gravity point from M1?',a:(d*Math.sqrt(M1)/(Math.sqrt(M1)+Math.sqrt(M2))/1e6).toFixed(1)+'e6 m',hint:'r1 = d*sqrt(m1)/(sqrt(m1)+sqrt(m2))',solution:'Formula: r1 = d*sqrt(m1)/(sqrt(m1)+sqrt(m2)) → ' + ('' + d + '*' + 'Math.sqrt' + '(' + M1 + ')' + '/' + '(' + 'Math.sqrt' + '(' + M1 + ')' + '+' + 'Math.sqrt' + '(' + M2 + ')' + ')' + '/' + '1e6') + ' = ' + ((d*Math.sqrt(M1)/(Math.sqrt(M1)+Math.sqrt(M2))/1e6).toFixed(1)+'e6 m')}; },
