    function () { var m=rand(500,2000); var r=rand(2,5)*6.4e6; return {q:'Satellite m='+m+' kg, r='+(r/1e6).toFixed(1)+'e6 m. Binding energy?',a:(6.67e-11*6e24*m/(2*r)/1e6).toFixed(2)+' MJ',hint:'BE = GMm/(2r)',solution:'Formula: BE = GMm/(2r) → ' + ('' + '6.67e-11' + '*' + '6e24' + '*' + m + '/' + '(' + '2' + '*' + r + ')' + '/' + '1e6') + ' = ' + ((6.67e-11*6e24*m/(2*r)/1e6).toFixed(2)+' MJ')}; },
    function () { var r1=6.4e6+200e3; var r2=6.4e6+36000e3; var v1=Math.sqrt(6.67e-11*6e24/r1); var v2=Math.sqrt(6.67e-11*6e24/r2); var dv=v2*Math.sqrt(r2/r1)-v1; return {q:'Hohmann transfer from 200 km to GEO. Delta-v for first burn?',a:(dv/1000).toFixed(2)+' km/s',hint:'Delta_v = v2*sqrt(r2/r1) - v1',solution:'Formula: Delta_v = v2*sqrt(r2/r1) - v1 → ' + ('' + dv + '/' + '1000') + ' = ' + ((dv/1000).toFixed(2)+' km/s')}; },
