    function () { var L=rand(5,20)/10; var v=340; return {q:'Open pipe vs closed pipe L='+(L*100).toFixed(0)+' cm. Fundamental f ratio (open/closed)?',a:'2:1',hint:'f_open = v/2L, f_closed = v/4L',solution:'f_open = v/2L, f_closed = v/4L → ' + ('2:1')}; },
