    function () { var L=rand(1,10)/1000; var C=rand(10,100)*1e-6; var R=rand(10,50); var w=1/Math.sqrt(L*C); var Q=R===0?'Infinite':(Math.sqrt(L/C)/R).toFixed(2); return {q:'Series LCR: L='+(L*1000)+' mH, C='+(C*1e6).toFixed(0)+' uF. Quality factor if R=0?',a:Q,hint:'Q = (1/R)*sqrt(L/C) for series',solution:'Formula: Q = (1/R)*sqrt(L/C) for series → ' + ('' + Q) + ' = ' + (Q)}; },
    function () { return {q:'Wattless current: power consumed in pure inductor or capacitor?',a:'Zero (phase difference of 90°)',hint:'P = VI cos(phi), cos(90)=0',solution:'P = VI cos(phi), cos(90)=0 → ' + ('Zero (phase difference of 90°)')}; },
    function () { var L=rand(1,10)/1000; var C=rand(10,100)*1e-6; var f=1/(2*Math.PI*Math.sqrt(L*C)); return {q:'LC oscillations: L='+(L*1000)+' mH, C='+(C*1e6).toFixed(0)+' uF. Angular frequency?',a:(2*Math.PI*f).toFixed(1)+' rad/s',hint:'omega = 1/sqrt(LC)',solution:'Formula: omega = 1/sqrt(LC) → ' + ('' + '2' + '*' + 'Math.PI' + '*' + f) + ' = ' + ((2*Math.PI*f).toFixed(1)+' rad/s')}; },
