    function () { var T_h=rand(500,800); var T_c=rand(200,350); return {q:'Carnot engine: T_h='+T_h+' K, T_c='+T_c+' K. Efficiency?',a:((1-T_c/T_h)*100).toFixed(1)+'%',hint:'eta = 1 - T_c/T_h. Carnot is most efficient heat engine',solution:'Formula: eta = 1 - T_c/T_h. Carnot is most efficient heat engine → ' + ('' + '(' + '1' + '-' + T_c + '/' + T_h + ')' + '*' + '100') + ' = ' + (((1-T_c/T_h)*100).toFixed(1)+'%')}; },
    function () { return {q:'Third law: residual entropy?',a:'Entropy remaining at 0K due to disorder (e.g., CO crystal has residual entropy R ln2 due to random CO orientations)',hint:'Perfectly ordered crystal has S=0 at 0K. Disordered crystals have residual entropy',solution:'Perfectly ordered crystal has S=0 at 0K. Disordered crystals have residual entropy → ' + ('Entropy remaining at 0K due to disorder (e.g., CO crystal has residual entropy R ln2 due to random CO orientations)')}; },
