    function () { var t=rand(5,60); var k=Math.log(2)/t; return {q:'t_1/2='+t+' min. Time for 90% completion? (1st order)',a:(Math.log(10)/k).toFixed(0)+' min',hint:'t = (1/k)ln([A]0/[A])',solution:'Formula: t = (1/k)ln([A]0/[A]) → ' + ('' + 'Math.log' + '(' + '10' + ')' + '/' + k) + ' = ' + ((Math.log(10)/k).toFixed(0)+' min')}; },
    function () { var a=rand(1,5); var t=rand(5,30); var k_s=1/t; var t12=Math.log(2)/k_s; return {q:'Initial rate = '+a+' M/s, t=5 min. Approx k? (1st order)',a:k_s.toFixed(3)+' min^-1',hint:'r0 = k[A]0',solution:'Formula: r0 = k[A]0 → ' + ('' + k_s) + ' = ' + (k_s.toFixed(3)+' min^-1')}; },
