    function () { var n=pick([0,1,2]); return {q:'Units of k for '+n+'th order?',a:n===0?'M s^-1':(n===1?'s^-1':'M^-1 s^-1'),hint:'k units: M^(1-n) s^-1',solution:'k units: M^(1-n) s^-1 → ' + (n===0?'M s^-1':(n===1?'s^-1':'M^-1 s^-1'))}; },
    function () { var a=rand(1,5); var b=rand(1,5); return {q:'Rate = k[A]^2[B]. If [A] triples, [B] halves. Rate change?',a:(9*0.5).toFixed(1)+'x',hint:'Rate prop to [A]^2[B] => 3^2*0.5 = 4.5x',solution:'Formula: Rate prop to [A]^2[B] => 3^2*0.5 = 4.5x → ' + ('' + '9' + '*' + '0.5') + ' = ' + ((9*0.5).toFixed(1)+'x')}; },
    function () { var C0=rand(1,5); var t=rand(5,30); var k=0.693/t; return {q:'[A]0='+C0+' M, t_1/2='+t+' min. k for 1st order?',a:k.toFixed(4)+' min^-1',hint:'k = 0.693/t_1/2',solution:'Formula: k = 0.693/t_1/2 → ' + ('' + k) + ' = ' + (k.toFixed(4)+' min^-1')}; },
    function () { var t=rand(5,30); var k=0.693/t; var t75=Math.log(1/0.25)/k; return {q:'t_1/2='+t+' min. Time for 75% completion?',a:t75.toFixed(0)+' min',hint:'t = (1/k)ln([A]0/[A]) = ln4/k = 2*t_1/2',solution:'Formula: t = (1/k)ln([A]0/[A]) = ln4/k = 2*t_1/2 → ' + ('' + t75) + ' = ' + (t75.toFixed(0)+' min')}; },
    function () { var k=rand(0.1,1); var t=rand(2,10); var frac=1-Math.exp(-k*t); return {q:'k='+k.toFixed(1)+' min^-1, t='+t+' min. Fraction reacted? (1st order)',a:frac.toFixed(3),hint:'Fraction reacted = 1 - e^(-kt)',solution:'Formula: Fraction reacted = 1 - e^(-kt) → ' + ('' + frac) + ' = ' + (frac.toFixed(3))}; },
    function () { var Ea=rand(50,150)*1000; var T1=300; var T2=rand(310,350); var k_ratio=Math.exp(Ea/8.314*(1/T1-1/T2)); return {q:'Arrhenius: Ea='+(Ea/1000).toFixed(0)+' kJ/mol. Rate ratio at '+T2+' K vs '+T1+' K?',a:k_ratio.toFixed(2),hint:'ln(k2/k1) = -(Ea/R)(1/T2-1/T1)',solution:'Formula: ln(k2/k1) = -(Ea/R)(1/T2-1/T1) → ' + ('' + k_ratio) + ' = ' + (k_ratio.toFixed(2))}; },
    function () { var k1=rand(1,10)/100; var T1=300; var k2=rand(2,20)/100; var T2=rand(310,320); var Ea=-8.314*Math.log(k2/k1)/(1/T2-1/T1); return {q:'k1='+k1.toFixed(3)+' at '+T1+' K, k2='+k2.toFixed(3)+' at '+T2+' K. Activation energy?',a:(Ea/1000).toFixed(0)+' kJ/mol',hint:'ln(k2/k1) = -Ea/R(1/T2-1/T1)',solution:'Formula: ln(k2/k1) = -Ea/R(1/T2-1/T1) → ' + ('' + Ea + '/' + '1000') + ' = ' + ((Ea/1000).toFixed(0)+' kJ/mol')}; },
