    function () { return {q:'Rate-determining step: concept?',a:'Slowest step in a multi-step reaction determines overall rate',hint:'Like the slowest bottleneck in a process',solution:'Like the slowest bottleneck in a process → ' + ('Slowest step in a multi-step reaction determines overall rate')}; },
    function () { var Ea_f=rand(50,150)*1000; var dH_val=rand(-50,-10)*1000; return {q:'Ea forward='+(Ea_f/1000).toFixed(0)+' kJ, dH='+(dH_val/1000).toFixed(0)+' kJ (exo). Ea backward?',a:((Ea_f-dH_val)/1000).toFixed(0)+' kJ/mol',hint:'Ea(back) = Ea(forward) - dH (for exothermic: Ea_back > Ea_forward)',solution:'Formula: Ea(back) = Ea(forward) - dH (for exothermic: Ea_back > Ea_forward) → ' + ('' + '(' + Ea_f + '-' + dH_val + ')' + '/' + '1000') + ' = ' + (((Ea_f-dH_val)/1000).toFixed(0)+' kJ/mol')}; },
