    function () { var c=pick(["CH3NH2","C6H5NH2","(CH3)2NH","(CH3)3N"]); return {q:'Name of '+c+'?',a:['Methylamine (1o)','Aniline (1o aromatic)','Dimethylamine (2o)','Trimethylamine (3o)'][["CH3NH2","C6H5NH2","(CH3)2NH","(CH3)3N"].indexOf(c)],hint:'Amine classification based on N-substitution',solution:'Amine classification based on N-substitution → ' + (['Methylamine (1o)','Aniline (1o aromatic)','Dimethylamine (2o)','Trimethylamine (3o)'][["CH3NH2","C6H5NH2","(CH3)2NH","(CH3)3N"].indexOf(c)])}; },
