    function () { return {q:'Sandmeyer reaction: C6H5N2Cl + CuCl?',a:'C6H5Cl + N2',hint:'Replacement of diazonium by Cl, Br, CN',solution:'Replacement of diazonium by Cl, Br, CN → ' + ('C6H5Cl + N2')}; },
    function () { return {q:'Gabriel phthalimide synthesis for?',a:'Primary amines from alkyl halides',hint:'K phthalimide + RX -> RNH2',solution:'K phthalimide + RX -> RNH2 → ' + ('Primary amines from alkyl halides')}; },
    function () { return {q:'Hoffmann bromamide degradation?',a:'RCONH2 + Br2 + NaOH -> RNH2',hint:'Amide -> primary amine (C loss)',solution:'Amide -> primary amine (C loss) → ' + ('RCONH2 + Br2 + NaOH -> RNH2')}; },
    function () { return {q:'Which is most basic: NH3, RNH2, R2NH, R3N?',a:'Usually R2NH > RNH2 > R3N > NH3 (in water)',hint:'Depends on solvation and +I effects',solution:'Depends on solvation and +I effects → ' + ('Usually R2NH > RNH2 > R3N > NH3 (in water)')}; },
