    function () { return {q:'N-ethylation of aniline with C2H5Br?',a:'N-Ethylaniline (then N,N-diethylaniline)',hint:'Alkylation of amines',solution:'Alkylation of amines → ' + ('N-Ethylaniline (then N,N-diethylaniline)')}; },
    function () { return {q:'Amines: lower bp than alcohols?',a:'Yes (N-H weaker H-bond than O-H)',hint:'Alcohols have stronger H-bonding',solution:'Alcohols have stronger H-bonding → ' + ('Yes (N-H weaker H-bond than O-H)')}; },
    function () { return {q:'Quaternary ammonium salts: properties?',a:'Cationic surfactants, phase transfer catalysts',hint:'R4N+X-: soluble in both phases',solution:'R4N+X-: soluble in both phases → ' + ('Cationic surfactants, phase transfer catalysts')}; },
