    function () { return makeBioQ("Algae: main types?","Chlorophyceae (green), Phaeophyceae (brown), Rhodophyceae (red)",["Green only","Green+Brown+Red","Red only","Brown only"],"Based on pigment, cell wall, stored food","Green: Chlamydomonas, Brown: Sargassum, Red: Gracilaria"); },
    function () { return makeBioQ("Bryophytes: example?","Mosses (Funaria, Sphagnum), Liverworts (Marchantia)",["Moss","Liverwort","Both","None"],"Non-vascular plants, need water for fertilization","Sphagnum: peat moss used as fuel, soil conditioner"); },
    function () { return makeBioQ("Pteridophytes: first?","Vascular plants (have xylem and phloem)",["Non-vascular","Vascular","Seeded","Flowering"],"Ferns, horsetails, club mosses","Dominant generation: sporophyte (unlike bryophytes)"); },
