    function () { return makeBioQ("Vertebrata: subclasses?","Pisces, Amphibia, Reptilia, Aves, Mammalia (5 classes)",["5 classes","4 classes","6 classes","7 classes"],"Vertebral column present","Cyclostomata (jawless fish, lamprey, hagfish): primitive vertebrates"); },
    function () { return makeBioQ("Cyclostomata: feature?","Jawless fish (lamprey, hagfish), ectoparasites on fish",["Jawless","Bony","Cartilaginous","Jawed"],"Most primitive vertebrates","Round mouth with horny teeth, no scales"); },
