    function () { return makeBioQ("Viruses: structure?","DNA or RNA genome, capsid (protein coat), some have envelope (lipid bilayer)",["DNA+RNA","DNA or RNA","Only DNA","Only RNA"],"Obligate intracellular parasites, use host machinery","Bacteriophage: virus that infects bacteria (T4 phage)"); },
    function () { return makeBioQ("T4 bacteriophage structure?","Head (DNA), Collar, Tail sheath, Tail fibers (attachment to bacteria)",["Head","Tail","Fibers","All parts"],"Icosahedral head, contractile tail sheath","Injects DNA into bacterial host"); },
    function () { return makeBioQ("Tobacco Mosaic Virus (TMV)?","RNA virus, rod-shaped, infects tobacco plants (first virus discovered)",["DNA virus","RNA virus","Both","Neither"],"Discovered by Iwanowski (1892), crystallized by Stanley (1935)","Helical capsid, ssRNA genome"); },
