function () { var m=rand(100,500)/1000; var c=rand(200,900); var dT=rand(10,50); var Q=m*c*dT; return {q:'Mass '+(m*1000).toFixed(0)+' g, c='+c+' J/kgK, dT='+dT+' K. Heat required?',a:Q.toFixed(0)+' J',hint:'Q = mc dT',solution:'Formula: Q = mc dT -> ' + m + 'x' + c + 'x' + dT + ' = ' + Q.toFixed(0) + ' J'}; },
function () { var m1=rand(100,500)/1000; var T1=rand(60,90); var m2=rand(100,500)/1000; var T2=rand(10,30); var c=4200; var Tf=(m1*T1+m2*T2)/(m1+m2); return {q:'m1='+(m1*1000).toFixed(0)+' g at '+T1+' C mixed with m2='+(m2*1000).toFixed(0)+' g at '+T2+' C. Final temperature?',a:Tf.toFixed(1)+' C',hint:'Heat lost = Heat gained',solution:'Heat lost = Heat gained -> Tf = (' + m1 + 'x' + T1 + '+' + m2 + 'x' + T2 + ')/(' + m1 + '+' + m2 + ') = ' + Tf.toFixed(1) + ' C'}; },
function () { var m=rand(10,100)/1000; var Lf=rand(80,340)*1000; var Q=m*Lf; return {q:'Ice m='+(m*1000).toFixed(0)+' g at 0 C melts. Heat absorbed? (Lf='+(Lf/1000).toFixed(0)+' kJ/kg)',a:Q.toFixed(0)+' J',hint:'Q = mLf',solution:'Formula: Q = mLf -> ' + m + 'x' + Lf + ' = ' + Q.toFixed(0) + ' J'}; },
function () { var m=rand(10,50)/1000; var Lv=rand(540,2260)*1000; var Q=m*Lv; return {q:'Water '+(m*1000).toFixed(0)+' g at 100 C vaporizes. Heat required? (Lv='+(Lv/1000).toFixed(0)+' kJ/kg)',a:Q.toFixed(0)+' J',hint:'Q = mLv',solution:'Formula: Q = mLv -> ' + m + 'x' + Lv + ' = ' + Q.toFixed(0) + ' J'}; },
function () { var k=rand(50,400); var A=rand(1,5)/100; var dT=rand(10,50); var d=rand(1,5)/100; var Q=k*A*dT/d; return {q:'Rod: k='+k+' W/mK, A='+(A*100).toFixed(1)+' cm^2, dT='+dT+' K, L='+(d*100).toFixed(1)+' cm. Heat current?',a:Q.toFixed(2)+' W',hint:'dQ/dt = kA(dT/L)',solution:'Formula: dQ/dt = kA(dT/L) -> ' + k + 'x' + A + 'x' + dT + '/' + d + ' = ' + Q.toFixed(2) + ' W'}; },
function () { var T0=rand(50,90); var Ts=rand(20,30); var t=rand(5,30); var k=rand(0.02,0.08); var T=Ts+(T0-Ts)*Math.exp(-k*t); return {q:'Body at '+T0+' C, surrounding '+Ts+' C. Temperature after '+t+' min? (k='+k+'/min)',a:T.toFixed(1)+' C',hint:'Newton cooling: T = Ts + (T0-Ts)e^(-kt)',solution:'Newton cooling: T = Ts + (T0-Ts)e^(-kt) -> T = ' + T.toFixed(1) + ' C'}; },
