function () { var T=rand(500,3000); var A=rand(1,10)/10000; var s=5.67e-8; var P=A*s*Math.pow(T,4); return {q:'Blackbody: A='+(A*10000).toFixed(1)+' cm^2, T='+T+' K. Radiant power?',a:P.toFixed(2)+' W',hint:'P = A sigma T^4, sigma = 5.67x10^-8',solution:'Formula: P = A sigma T^4 -> ' + A + 'x5.67e-8x' + T + '^4 = ' + P.toFixed(2) + ' W'}; },
function () { var a=rand(1,3)/100000; var L=rand(1,5); var dT=rand(20,60); var dL=L*a*dT; return {q:'Rail L='+L+' m, a='+a+' /K, dT='+dT+' K. Gap needed?',a:(dL*1000).toFixed(2)+' mm',hint:'Gap = dL = L a dT',solution:'Formula: Gap = dL = L a dT -> ' + L + 'x' + a + 'x' + dT + ' = ' + (dL*1000).toFixed(2) + ' mm'}; },
function () { var m=rand(50,200)/1000; var c=rand(200,900); var C=m*c; return {q:'Mass '+(m*1000).toFixed(0)+' g, c='+c+' J/kgK. Heat capacity?',a:C.toFixed(2)+' J/K',hint:'C = mc',solution:'Formula: C = mc -> ' + m + 'x' + c + ' = ' + C.toFixed(2) + ' J/K'}; },
function () { var m=rand(50,200)/1000; var c=rand(200,900); var W=m*c/4200; return {q:'Mass '+(m*1000).toFixed(0)+' g, c='+c+' J/kgK. Water equivalent?',a:(W*1000).toFixed(1)+' g',hint:'W = mc/4200 (in kg)',solution:'Formula: W = mc/4200 -> ' + m + 'x' + c + '/4200 = ' + (W*1000).toFixed(1) + ' g'}; },
function () { var m1=rand(100,300)/1000; var T1=rand(70,98); var m2=rand(50,100)/1000; var T2=rand(0,10); var c1=4200; var c2=2100; var Lf=334000; var Q1=m1*c1*T1; var Q2=m2*c2*(0-T2)+m2*Lf; var Tf=(Q1-Q2)/((m1+m2)*4200); return {q:'Water '+(m1*1000).toFixed(0)+' g at '+T1+' C + ice '+(m2*1000).toFixed(0)+' g at '+T2+' C. Final temp?',a:Tf.toFixed(1)+' C',hint:'Heat lost by water = heat to warm ice + melt + warm melted ice water',solution:'Calorimetry: Q_lost = Q_gained -> Tf = ' + Tf.toFixed(1) + ' C'}; },
