function () { return {q:'Temperature at which all three scales (C, F, K) coincide?',a:'-40 (C=F). No scale matches Kelvin at that temp',hint:'C/5 = (F-32)/9. Set C=F gives C = -40',solution:'C/5 = (F-32)/9. Set C=F gives C = -40 -> -40 (C=F)'}; },
function () { return {q:'Absolute zero in Celsius?',a:'-273.15 C',hint:'Absolute zero = 0 K = -273.15 C',solution:'Absolute zero = 0 K = -273.15 C -> -273.15 C'}; },
function () { var a=rand(1,3)/100000; var L=rand(1,5); var dT=rand(20,50); var Y=2e11; var A=rand(1,5)/10000; var F=Y*A*a*dT; return {q:'Rod clamped: L='+L+' m, A='+(A*10000).toFixed(2)+' mm^2, a='+a+' /K, dT='+dT+' K, Y=2e11 Pa. Thermal force?',a:F.toFixed(0)+' N',hint:'Thermal stress = Y a dT, Force = stress x A',solution:'Thermal stress = Y a dT -> F = Y a dT A = ' + F.toFixed(0) + ' N'}; },
function () { var a1=rand(1,3)/100000; var a2=rand(1,3)/100000; var L0=rand(1,5); var dT=rand(20,50); var dL=L0*(a2-a1)*dT; return {q:'Bimetallic strip: a1='+a1+' /K, a2='+a2+' /K, L='+L0+' m, dT='+dT+' K. Which way does it bend?',a:'Bends towards metal with lower a. dL diff = ' + (dL*1000).toFixed(2) + ' mm',hint:'Metal with higher a expands more -> bends toward metal with lower a',solution:'Metal with higher a expands more -> dL diff = ' + (dL*1000).toFixed(2) + ' mm'}; },
function () { var T=rand(500,3000); var s=5.67e-8; var R=s*Math.pow(T,4); return {q:'Blackbody at '+T+' K. Radiant emittance (power per unit area)?',a:R.toFixed(0)+' W/m^2',hint:'R = sigma T^4',solution:'Formula: R = sigma T^4 -> 5.67e-8x' + T + '^4 = ' + R.toFixed(0) + ' W/m^2'}; },
