function () { var T1=rand(300,500); var T2=rand(600,1200); var R=Math.pow(T2/T1,4); return {q:'Temp goes from '+T1+' K to '+T2+' K. Power ratio?',a:R.toFixed(1),hint:'P prop to T^4. Ratio = (T2/T1)^4',solution:'Formula: P prop to T^4 -> (' + T2 + '/' + T1 + ')^4 = ' + R.toFixed(1)}; },
function () { var lam=rand(400,600)*1e-9; var T=2.898e-3/lam; return {q:'lambda_max='+(lam*1e9).toFixed(0)+' nm. Temperature?',a:T.toFixed(0)+' K',hint:'T = b/lambda_max, b = 2.898x10^-3',solution:'Formula: T = b/lambda_max -> 2.898e-3/' + lam + ' = ' + T.toFixed(0) + ' K'}; },
function () { var m=rand(1,5); var c=rand(200,900); var dT=rand(10,40); var t=rand(60,600); var k=(m*c/t)*Math.log(dT/10); return {q:'Object cools from dT='+dT+' C to 10 C above surroundings in '+(t/60).toFixed(0)+' min. Cooling constant k?',a:k.toFixed(4)+' /s',hint:'ln(dT1/dT2) = kt. k = ln(dT1/dT2)/t',solution:'ln(dT1/dT2)/t = k -> ln(' + dT + '/10)/' + t + ' = ' + k.toFixed(4) + ' /s'}; },
function () { var m=rand(100,500)/1000; var c=4200; var dT=rand(20,50); var t=rand(120,600); var P=m*c*dT/t; return {q:'Water '+(m*1000).toFixed(0)+' g heated from 25 to '+(25+dT)+' C in '+(t/60).toFixed(1)+' min. Heater power?',a:P.toFixed(1)+' W',hint:'P = mc dT/t',solution:'Formula: P = mc dT/t -> ' + m + 'x4200x' + dT + '/' + t + ' = ' + P.toFixed(1) + ' W'}; },
