function () { return {q:'EM spectrum: order from lowest to highest frequency?',a:'Radio, Microwave, IR, Visible, UV, X-ray, Gamma',hint:'Remember: R (radio) to G (gamma) - increasing f',solution:'Radio < Microwave < IR < Visible < UV < X-ray < Gamma'}; },
function () { return {q:'Which EM waves are used in radar?',a:'Microwaves',hint:'Radar uses microwaves for detection and ranging',solution:'Radar uses microwaves -> Microwaves'}; },
function () { return {q:'Which EM waves are used in remote controls?',a:'Infrared (IR) waves',hint:'IR is used in TV remote, night vision etc',solution:'Remote controls use IR -> Infrared (IR)'}; },
function () { return {q:'Which EM waves are used in medical imaging (bone fractures)?',a:'X-rays',hint:'X-rays penetrate soft tissue but are absorbed by bones',solution:'X-rays are used for bone imaging -> X-rays'}; },
function () { return {q:'Which EM waves cause sunburn?',a:'Ultraviolet (UV) rays',hint:'UV from sun damages DNA cells in skin',solution:'Sunburn caused by UV -> Ultraviolet (UV)'}; },
function () { return {q:'Displacement current: which equation includes it?',a:"Ampere-Maxwell law: curl B = u0 J + u0 e0 dE/dt",hint:'Maxwell added displacement current to Ampere law',solution:"Ampere-Maxwell law: curl B = u0 J + u0 e0 dE/dt"}; },
function () { var E=rand(1,10); var c=3e8; var B=E/c; return {q:'E field amplitude ' + E + ' V/m in EM wave. B field amplitude?',a:B.toExponential(2)+' T',hint:'E0 = c B0',solution:'Formula: B0 = E0/c -> ' + E + '/3e8 = ' + B.toExponential(2) + ' T'}; },
function () { var B=rand(1,10)/1e6; var c=3e8; var E=c*B; return {q:'B field amplitude '+(B*1e6).toFixed(2)+' uT in EM wave. E amplitude?',a:E.toFixed(2)+' V/m',hint:'E0 = c B0',solution:'Formula: E0 = c B0 -> 3e8x' + B + ' = ' + E.toFixed(2) + ' V/m'}; },
function () { var E=rand(1,10); var c=3e8; var e0=8.85e-12; var I=0.5*c*e0*E*E; return {q:'E ' + E + ' V/m. Intensity of EM wave?',a:I.toFixed(3)+' W/m^2',hint:'I = 0.5 c e0 E0^2',solution:'I = 0.5 c e0 E0^2 -> 0.5x3e8x8.85e-12x' + E + '^2 = ' + I.toFixed(3) + ' W/m^2'}; },
