function () { var P=rand(10,100); var r=rand(1,10); var I=P/(4*Math.PI*r*r); return {q:'Source power ' + P + ' W at distance ' + r + ' m. Intensity?',a:I.toFixed(4)+' W/m^2',hint:'I = P/(4 pi r^2)',solution:'Formula: I = P/(4 pi r^2) -> ' + P + '/(4x3.14x' + r + '^2) = ' + I.toFixed(4) + ' W/m^2'}; },
function () { return {q:'In which direction does EM wave energy flow?',a:'Direction of Poynting vector S = (ExB)/u0',hint:'S points in direction of wave propagation',solution:'Poynting vector S = (ExB)/u0 -> direction of S = propagation direction'}; },
