function () { var R=rand(10,100); var C=rand(10,100)/1e6; var f=rand(50,60); var XC=1/(2*Math.PI*f*C); var Z=Math.sqrt(R*R+XC*XC); return {q:'R='+R+' ohm, C='+(C*1e6).toFixed(0)+' uF, f='+f+' Hz. Impedance (RC)?',a:Z.toFixed(2)+' ohm',hint:'Z = sqrt(R^2 + XC^2)',solution:'Formula: Z = sqrt(R^2 + XC^2) -> sqrt(' + R + '^2+' + XC.toFixed(2) + '^2) = ' + Z.toFixed(2) + ' ohm'}; },
function () { var R=rand(10,50); var L=rand(1,500)/1000; var C=rand(10,100)/1e6; var f=rand(50,60); var XL=2*Math.PI*f*L; var XC=1/(2*Math.PI*f*C); var Z=Math.sqrt(R*R+(XL-XC)*(XL-XC)); return {q:'R='+R+' ohm, L='+(L*1000).toFixed(0)+' mH, C='+(C*1e6).toFixed(0)+' uF, f='+f+' Hz. Z?',a:Z.toFixed(2)+' ohm',hint:'Z = sqrt(R^2 + (XL-XC)^2)',solution:'Formula: Z = sqrt(R^2 + (XL-XC)^2) -> sqrt(' + R + '^2+(' + XL.toFixed(2) + '-' + XC.toFixed(2) + ')^2) = ' + Z.toFixed(2) + ' ohm'}; },
function () { var L=rand(1,500)/1000; var C=rand(10,100)/1e6; var f0=1/(2*Math.PI*Math.sqrt(L*C)); return {q:'L='+(L*1000).toFixed(0)+' mH, C='+(C*1e6).toFixed(0)+' uF. Resonant frequency?',a:f0.toFixed(1)+' Hz',hint:'f0 = 1/(2 pi sqrt(LC))',solution:'Formula: f0 = 1/(2 pi sqrt(LC)) -> 1/(2x3.14xsqrt(' + L + 'x' + C + ')) = ' + f0.toFixed(1) + ' Hz'}; },
function () { var L=rand(1,500)/1000; var C=rand(10,100)/1e6; var f0=1/(2*Math.PI*Math.sqrt(L*C)); return {q:'RLC: L='+(L*1000).toFixed(0)+' mH, C='+(C*1e6).toFixed(0)+' uF. f0? If R halved, f0?',a:f0.toFixed(1)+' Hz. f0 independent of R',hint:'f0 = 1/(2 pi sqrt(LC)). f0 does not depend on R',solution:'f0 does not depend on R -> f0 = ' + f0.toFixed(1) + ' Hz'}; },
function () { var V=rand(100,300); var I=rand(1,10); var R=rand(10,50); var P=I*I*R; return {q:'R='+R+' ohm, I='+I+' A. Power dissipated?',a:P.toFixed(1)+' W',hint:'P = I^2 R (rms values)',solution:'Formula: P = I^2 R -> ' + I + '^2x' + R + ' = ' + P.toFixed(1) + ' W'}; },
function () { var V=rand(100,300); var I=rand(1,10); var p=rand(0.5,1); var Q=V*I*Math.sqrt(1-p*p); return {q:'VI='+(V*I).toFixed(0)+' VA, pf='+p.toFixed(2)+'. Reactive power?',a:Q.toFixed(1)+' VAR',hint:'Q = VI sin(phi), sin(phi) = sqrt(1-pf^2)',solution:'Q = VI sin(phi) -> ' + V + 'x' + I + 'xsqrt(1-' + p.toFixed(2) + '^2) = ' + Q.toFixed(1) + ' VAR'}; },
function () { var V=rand(100,300); var I=rand(1,10); var S=V*I; return {q:'V='+V+' V, I='+I+' A. Apparent power?',a:S.toFixed(1)+' VA',hint:'S = VI',solution:'Formula: S = VI -> ' + V + 'x' + I + ' = ' + S.toFixed(1) + ' VA'}; },
function () { var V=rand(100,300); var I=rand(1,10); var p=rand(0.7,1); var P=V*I*p; return {q:'S='+(V*I).toFixed(0)+' VA, pf='+p.toFixed(2)+'. Real power?',a:P.toFixed(1)+' W',hint:'P = S x pf',solution:'Formula: P = S x pf -> ' + (V*I) + 'x' + p.toFixed(2) + ' = ' + P.toFixed(1) + ' W'}; },
function () { return {q:'In pure inductor: current leads or lags voltage? by how much?',a:'Current lags voltage by 90 deg (pi/2 rad)',hint:'For inductor: voltage leads current (ELI the ICE man)',solution:'Inductor: V leads I -> current lags by 90 deg'}; },
function () { return {q:'In pure capacitor: current leads or lags voltage? by how much?',a:'Current leads voltage by 90 deg (pi/2 rad)',hint:'ELI the ICE man: Capacitor: current leads voltage',solution:'Capacitor: I leads V -> current leads by 90 deg'}; },
function () { var V=rand(100,300); var f=rand(50,500); var C=rand(10,100)/1e6; var XC=1/(2*Math.PI*f*C); var I=V/XC; return {q:'V='+V+' V, f='+f+' Hz, C='+(C*1e6).toFixed(0)+' uF. AC through capacitor?',a:I.toFixed(3)+' A',hint:'XC = 1/(2 pi f C), I = V/XC',solution:'I = V/XC = V/(1/(2 pi f C)) = V 2 pi f C -> ' + V + 'x2x3.14x' + f + 'x' + C + ' = ' + I.toFixed(3) + ' A'}; },
function () { var V=rand(100,300); var f=rand(50,500); var L=rand(1,500)/1000; var XL=2*Math.PI*f*L; var I=V/XL; return {q:'V='+V+' V, f='+f+' Hz, L='+(L*1000).toFixed(0)+' mH. AC through inductor?',a:I.toFixed(3)+' A',hint:'XL = 2 pi f L, I = V/XL',solution:'I = V/(2 pi f L) -> ' + V + '/(2x3.14x' + f + 'x' + L + ') = ' + I.toFixed(3) + ' A'}; },
