function () { var Np=rand(100,500); var Ns=rand(100,500); var Vp=rand(100,300); var Is=rand(1,10); var Ip=Is*Ns/Np; return {q:'Transformer: Np='+Np+', Ns='+Ns+', Is='+Is+' A. Ip?',a:Ip.toFixed(3)+' A',hint:'Ip/Is = Ns/Np (ideal: power in = power out)',solution:'Ip/Is = Ns/Np -> Ip = ' + Is + 'x' + Ns + '/' + Np + ' = ' + Ip.toFixed(3) + ' A'}; },
