function () { var f=rand(50,60); var w=2*Math.PI*f; return {q:'AC frequency '+f+' Hz. Angular frequency?',a:w.toFixed(1)+' rad/s',hint:'omega = 2 pi f',solution:'omega = 2 pi f -> 2x3.14x' + f + ' = ' + w.toFixed(1) + ' rad/s'}; },
function () { var V0=rand(100,400); var w=rand(100,500); var t=rand(10,50)/1000; var v=V0*Math.sin(w*t); return {q:'v(t)='+V0+' sin('+w+'t) V. v at t='+(t*1000).toFixed(1)+' ms?',a:v.toFixed(2)+' V',hint:'v = V0 sin(omega t)',solution:'v = V0 sin(omega t) -> ' + V0 + ' sin(' + w + 'x' + t + ') = ' + v.toFixed(2) + ' V'}; },
function () { var L=rand(1,500)/1000; var C=rand(10,100)/1e6; var Q=1/L*Math.sqrt(L/C); return {q:'Series RLC: L='+(L*1000).toFixed(0)+' mH, C='+(C*1e6).toFixed(0)+' uF, R=1 ohm. Quality factor Q?',a:Q.toFixed(1),hint:'Q = (1/R) sqrt(L/C)',solution:'Q = (1/R) sqrt(L/C) -> (1/1) sqrt(' + L + '/' + C + ') = ' + Q.toFixed(1)}; },
function () { var V=rand(100,300); var I=rand(1,10); var p=rand(0.7,1); var phi=Math.acos(p); return {q:'V='+V+' V, I='+I+' A, pf='+p.toFixed(2)+'. Phase angle?',a:(phi*180/Math.PI).toFixed(1)+' deg',hint:'cos(phi) = pf -> phi = acos(pf)',solution:'phi = acos(pf) -> acos(' + p.toFixed(2) + ') = ' + (phi*180/Math.PI).toFixed(1) + ' deg'}; },
function () { var V=rand(100,300); var f=rand(50,60); var C=rand(10,100)/1e6; var P=2*Math.PI*f*C*V*V; return {q:'Power factor correction: V='+V+' V, f='+f+' Hz, C='+(C*1e6).toFixed(0)+' uF connected. Reactive power supplied?',a:P.toFixed(1)+' VAR',hint:'Q_c = 2 pi f C V^2',solution:'Q_c = 2 pi f C V^2 -> 2x3.14x' + f + 'x' + C + 'x' + V + '^2 = ' + P.toFixed(1) + ' VAR'}; },
function () { var V=rand(100,300); var I=rand(1,10); return {q:'AC V='+V+' V rms, I='+I+' A rms. Peak power?',a:(V*I*2).toFixed(1)+' W',hint:'p_peak = V0 I0 = (Vrms sqrt2)(Irms sqrt2) = 2 Vrms Irms',solution:'p_peak = 2 Vrms Irms -> 2x' + V + 'x' + I + ' = ' + (V*I*2).toFixed(1) + ' W'}; }
