function () { var a=rand(2,6); var t=rand(2,5); return {q:'From rest, a='+a+' m/s^2, then decelerates at same rate to stop. Total time='+(2*t)+' s. Total distance?',a:(a*t*t).toFixed(1)+' m',hint:'s = 2 x 0.5at^2 = at^2',solution:'s_total = at^2 = ' + a + 'x' + t + '^2 = ' + (a*t*t).toFixed(1) + ' m'}; },
