function () { var u=rand(10,30); var th=45; var g=10; return {q:'Prove max range for projectile occurs at 45 deg using formula?',a:'R = u^2 sin(2th)/g. sin(2th) max at 2th=90 -> th=45',hint:'R prop to sin(2th). sin max = 1 at 90 deg',solution:'R = u^2 sin(2th)/g. sin(2th) max = 1 at 2th=90 deg -> th=45 deg'}; },
