function () { var w=rand(10,40); var I=rand(1,5); var KE=0.5*I*w*w; return {q:'I='+I+' kg m^2, w='+w+' rad/s. Rotational KE?',a:KE.toFixed(1)+' J',hint:'KE_rot = 0.5 I omega^2',solution:'KE_rot = 0.5 I omega^2 = 0.5x' + I + 'x' + w + '^2 = ' + KE.toFixed(1) + ' J'}; },
function () { var m=rand(1,5); var v=rand(5,15); var r=rand(1,5)/10; var L=m*v*r; return {q:'Particle m='+m+' kg, v='+v+' m/s at r='+r+' m from axis. Angular momentum?',a:L.toFixed(2)+' kg m^2/s',hint:'L = mvr (perpendicular)',solution:'L = mvr = ' + m + 'x' + v + 'x' + r + ' = ' + L.toFixed(2) + ' kg m^2/s'}; },
function () { var F=rand(10,40); var r=rand(1,5)/10; var tau=F*r; return {q:'F='+F+' N at r='+r+' m perpendicular. Torque?',a:tau.toFixed(2)+' Nm',hint:'tau = Fr',solution:'tau = Fr = ' + F + 'x' + r + ' = ' + tau.toFixed(2) + ' Nm'}; },
function () { var F=rand(10,40); var r=rand(1,5)/10; var th=rand(30,60); var tau=F*r*Math.sin(th*Math.PI/180); return {q:'F='+F+' N at r='+r+' m, angle='+th+' deg. Torque?',a:tau.toFixed(2)+' Nm',hint:'tau = Fr sin(theta)',solution:'tau = Fr sin(theta) = ' + F + 'x' + r + 'xsin(' + th + ') = ' + tau.toFixed(2) + ' Nm'}; },
function () { var M=rand(2,10); var R=rand(1,5)/10; var I=0.5*M*R*R; return {q:'Solid cylinder M='+M+' kg, R='+R+' m. Moment of inertia?',a:I.toFixed(3)+' kg m^2',hint:'I_solid_cylinder = 1/2 MR^2',solution:'I = 1/2 MR^2 = 0.5x' + M + 'x' + R + '^2 = ' + I.toFixed(3) + ' kg m^2'}; },
function () { var M=rand(2,10); var R=rand(1,5)/10; var I=M*R*R; return {q:'Thin ring M='+M+' kg, R='+R+' m. Moment of inertia?',a:I.toFixed(3)+' kg m^2',hint:'I_ring = MR^2',solution:'I = MR^2 = ' + M + 'x' + R + '^2 = ' + I.toFixed(3) + ' kg m^2'}; },
