function () { var A=rand(2,10); var w=rand(2,8); var t=rand(1,4); var x=A*Math.sin(w*t); return {q:'x = '+A+' sin('+w+'t) m. Displacement at t='+t+' s?',a:x.toFixed(2)+' m',hint:'x = A sin(omega t)',solution:'x = A sin(omega t) = ' + A + ' sin(' + w + 'x' + t + ') = ' + x.toFixed(2) + ' m'}; },
