function () { var A=rand(2,10); var w=rand(2,8); var a=-A*w*w; return {q:'x = '+A+' sin(wt). Max acceleration?',a:Math.abs(a).toFixed(2)+' m/s^2',hint:'a_max = A omega^2',solution:'a_max = A omega^2 = ' + A + 'x' + w + '^2 = ' + Math.abs(a).toFixed(2) + ' m/s^2'}; },
function () { var m=rand(1,5); var A=rand(2,10); var w=rand(2,8); var E=0.5*m*w*w*A*A; return {q:'SHM: m='+m+' kg, A='+A+' m, w='+w+' rad/s. Total energy?',a:E.toFixed(2)+' J',hint:'E_total = 0.5 m omega^2 A^2',solution:'E = 0.5 m w^2 A^2 = 0.5x' + m + 'x' + w + '^2x' + A + '^2 = ' + E.toFixed(2) + ' J'}; },
